=== FILE: tb/repro_period.v ===
`timescale 1ns / 1ps
// Repro, bucket A (period): with constant duty, rising edges of pwm must be
// PERIOD (8) clock cycles apart.
module tb_pwm_repro;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;

    integer passed = 0;
    integer failed = 0;
    integer timeouts = 0;
    integer cyc = 0;
    integer rise_count = 0;
    integer fall_count = 0;
    integer last_rise = 0;
    integer last_fall = 0;
    integer r1, r2, r3;
    reg     pwm_prev = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task step;
        begin
            @(negedge clk);
            cyc = cyc + 1;
            if (pwm === 1'b1 && pwm_prev !== 1'b1) begin
                rise_count = rise_count + 1;
                last_rise  = cyc;
            end
            if (pwm === 1'b0 && pwm_prev === 1'b1) begin
                fall_count = fall_count + 1;
                last_fall  = cyc;
            end
            pwm_prev = pwm;
        end
    endtask

    task wait_rise;
        integer n, start;
        begin
            start = rise_count;
            n = 0;
            while (rise_count == start && n < 64) begin
                step;
                n = n + 1;
            end
            if (rise_count == start) begin
                timeouts = timeouts + 1;
                $display("TIMEOUT waiting for a rising edge at cycle %0d", cyc);
            end
        end
    endtask

    task check;
        input            cond;
        input [8*48-1:0] label;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS %0s", label);
            end else begin
                failed = failed + 1;
                $display("FAIL %0s", label);
            end
        end
    endtask

    initial begin
        duty = 4'd3;
        rst  = 1'b1;
        repeat (4) step;
        rst = 1'b0;

        // duty 3: let it settle, then measure two rise-to-rise spacings
        wait_rise; wait_rise; wait_rise;
        r1 = last_rise; wait_rise; r2 = last_rise; wait_rise; r3 = last_rise;
        $display("duty 3: rise spacing %0d, %0d (expect 8)", r2 - r1, r3 - r2);
        check(r2 - r1 == 8, "period_duty3_first");
        check(r3 - r2 == 8, "period_duty3_second");

        // duty 5: settle, then measure again
        duty = 4'd5;
        wait_rise; wait_rise; wait_rise;
        r1 = last_rise; wait_rise; r2 = last_rise; wait_rise; r3 = last_rise;
        $display("duty 5: rise spacing %0d, %0d (expect 8)", r2 - r1, r3 - r2);
        check(r2 - r1 == 8, "period_duty5_first");
        check(r3 - r2 == 8, "period_duty5_second");

        check(timeouts == 0, "no_timeouts");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
