`timescale 1ns / 1ps
// Repro, bucket B (pulse width): with constant duty, pwm must be high for
// exactly `duty` consecutive cycles per period, and duty 0 keeps it low.
module tb_pwm_repro;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;

    integer passed = 0;
    integer failed = 0;
    integer timeouts = 0;
    integer cyc = 0;
    integer rise_count = 0;
    integer fall_count = 0;
    integer last_rise = 0;
    integer last_fall = 0;
    integer w1, w2;
    integer hi_cnt;
    reg     pwm_prev = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task step;
        begin
            @(negedge clk);
            cyc = cyc + 1;
            if (pwm === 1'b1 && pwm_prev !== 1'b1) begin
                rise_count = rise_count + 1;
                last_rise  = cyc;
            end
            if (pwm === 1'b0 && pwm_prev === 1'b1) begin
                fall_count = fall_count + 1;
                last_fall  = cyc;
            end
            pwm_prev = pwm;
        end
    endtask

    task wait_rise;
        integer n, start;
        begin
            start = rise_count;
            n = 0;
            while (rise_count == start && n < 64) begin
                step;
                n = n + 1;
            end
            if (rise_count == start) begin
                timeouts = timeouts + 1;
                $display("TIMEOUT waiting for a rising edge at cycle %0d", cyc);
            end
        end
    endtask

    task wait_fall;
        integer n, start;
        begin
            start = fall_count;
            n = 0;
            while (fall_count == start && n < 64) begin
                step;
                n = n + 1;
            end
            if (fall_count == start) begin
                timeouts = timeouts + 1;
                $display("TIMEOUT waiting for a falling edge at cycle %0d", cyc);
            end
        end
    endtask

    task check;
        input            cond;
        input [8*48-1:0] label;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS %0s", label);
            end else begin
                failed = failed + 1;
                $display("FAIL %0s", label);
            end
        end
    endtask

    initial begin
        duty = 4'd3;
        rst  = 1'b1;
        repeat (4) step;
        rst = 1'b0;

        // duty 3: settle, then measure two pulses
        wait_rise; wait_rise; wait_rise;
        wait_rise; wait_fall; w1 = last_fall - last_rise;
        wait_rise; wait_fall; w2 = last_fall - last_rise;
        $display("duty 3: high widths %0d, %0d (expect 3)", w1, w2);
        check(w1 == 3, "width_duty3_first");
        check(w2 == 3, "width_duty3_second");

        // duty 5: settle, then measure two pulses
        duty = 4'd5;
        wait_rise; wait_rise; wait_rise;
        wait_rise; wait_fall; w1 = last_fall - last_rise;
        wait_rise; wait_fall; w2 = last_fall - last_rise;
        $display("duty 5: high widths %0d, %0d (expect 5)", w1, w2);
        check(w1 == 5, "width_duty5_first");
        check(w2 == 5, "width_duty5_second");

        // duty 0: settle for three periods, then the output must stay low
        duty = 4'd0;
        repeat (24) step;
        hi_cnt = 0;
        repeat (16) begin
            step;
            if (pwm === 1'b1) hi_cnt = hi_cnt + 1;
        end
        $display("duty 0: %0d high cycles in 16 (expect 0)", hi_cnt);
        check(hi_cnt == 0, "duty0_stays_low");

        check(timeouts == 0, "no_timeouts");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
=== FILE: tb/repro_duty_update.v ===
`timescale 1ns / 1ps
// Repro, bucket C (duty update): duty is sampled once per period, so a change
// in the middle of a period must not alter that period. Checks compare against
// the period and width measured in this same run, so they do not depend on the
// absolute period length or pulse width.
module tb_pwm_repro;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd2;
    wire       pwm;

    integer passed = 0;
    integer failed = 0;
    integer timeouts = 0;
    integer cyc = 0;
    integer rise_count = 0;
    integer fall_count = 0;
    integer last_rise = 0;
    integer last_fall = 0;
    integer r1, r2, r3, p_meas, w_steady, w_dec;
    reg     pwm_prev = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task step;
        begin
            @(negedge clk);
            cyc = cyc + 1;
            if (pwm === 1'b1 && pwm_prev !== 1'b1) begin
                rise_count = rise_count + 1;
                last_rise  = cyc;
            end
            if (pwm === 1'b0 && pwm_prev === 1'b1) begin
                fall_count = fall_count + 1;
                last_fall  = cyc;
            end
            pwm_prev = pwm;
        end
    endtask

    task wait_rise;
        integer n, start;
        begin
            start = rise_count;
            n = 0;
            while (rise_count == start && n < 64) begin
                step;
                n = n + 1;
            end
            if (rise_count == start) begin
                timeouts = timeouts + 1;
                $display("TIMEOUT waiting for a rising edge at cycle %0d", cyc);
            end
        end
    endtask

    task wait_fall;
        integer n, start;
        begin
            start = fall_count;
            n = 0;
            while (fall_count == start && n < 64) begin
                step;
                n = n + 1;
            end
            if (fall_count == start) begin
                timeouts = timeouts + 1;
                $display("TIMEOUT waiting for a falling edge at cycle %0d", cyc);
            end
        end
    endtask

    task check;
        input            cond;
        input [8*48-1:0] label;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS %0s", label);
            end else begin
                failed = failed + 1;
                $display("FAIL %0s", label);
            end
        end
    endtask

    initial begin
        duty = 4'd2;
        rst  = 1'b1;
        repeat (4) step;
        rst = 1'b0;

        // Steady duty 2: settle, then measure the period in this run.
        wait_rise; wait_rise; wait_rise;
        wait_rise; r1 = last_rise;
        wait_rise; r2 = last_rise;
        p_meas = r2 - r1;
        $display("measured period %0d", p_meas);

        // Raise duty in mid-period, just after the pulse ends: the current
        // period must not change, so the next rise comes one period later.
        wait_fall;
        duty = 4'd5;
        wait_rise; r3 = last_rise;
        $display("after mid-period increase: rise %0d cycles after previous (expect %0d)",
                 r3 - r2, p_meas);
        check(r3 - r2 == p_meas, "increase_mid_period_waits_for_next_period");

        // Steady duty 5: settle, then measure the pulse width in this run.
        wait_rise; wait_rise;
        wait_rise; wait_fall; w_steady = last_fall - last_rise;

        // Lower duty just after a rise: the pulse in progress must keep its width.
        wait_rise;
        duty = 4'd1;
        wait_fall; w_dec = last_fall - last_rise;
        $display("steady duty-5 width %0d, width after mid-pulse decrease %0d",
                 w_steady, w_dec);
        check(w_dec == w_steady, "decrease_mid_pulse_keeps_width");

        check(timeouts == 0, "no_timeouts");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
